sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // deactivate the BR: "DocIntel Create Solution Definitions" if at all activated due to 3.1.1 overwriting with an active version of it
    // and let 3.1.1 use the new version of it named: "DocDataExtractor Create Solution Defs"
    var gr = new GlideRecord("sys_script");
    if (gr.get("36f0ba55eb331110f2549bf12a52281a") && gr.getValue("active") === "1") {
        gr.setValue("active", false);
        if (gr.update()) {
            gs.info(sn_i18n.Message.getMessage("platform-ml-di-deactivate-old-sol-defs", "Successfully deactivated the old BR: 'DocIntel Create Solution Definitions'"));
        } else {
            gs.info(sn_i18n.Message.getMessage("platform-ml-di-deactivate-old-sol-defs", "Failed to deactivate the old BR: 'DocIntel Create Solution Definitions'"));
        }
    }
    // deactivate the current BR as well as it is required to run only once.
    var sysScriptGr = new GlideRecord("sys_script");
    if (sysScriptGr.get("80473d55a3f23110f621495716fcdad6")) {
        sysScriptGr.setValue("active", false);
        if (sysScriptGr.update()) {
            gs.info(sn_i18n.Message.getMessage("platform-ml-di-deactivate-old-sol-defs", "Successfully deactivated the BR: 'Deactivate old solution def creation BR'"));
        } else {
            gs.info(sn_i18n.Message.getMessage("platform-ml-di-deactivate-old-sol-defs", "Failed to deactivate the BR: 'Deactivate old solution def creation BR'"));
        }
    }
})(current, previous);
